<script setup lang="ts">
// Port of bohr-model.tsx (React Three Fiber → TresJS).
// Auto-generated by gltfjsx, hand-ported to a Vue SFC: useGLTF + useAnimations,
// plus per-mesh material override.
import type { Group, Mesh, Object3D, AnimationClip, MeshStandardMaterial as ISMR } from 'three'
import { Color, MeshPhysicalMaterial } from 'three'
import type { Ref } from 'vue'
import { useGLTF, useAnimations } from '@tresjs/cientos'

const props = defineProps<{ modelUrl: string }>()

const group = ref<Group | null>(null)

type GLTFResult = {
  scene: Group
  nodes: Record<string, Mesh>
  materials: Record<string, ISMR>
  animations: AnimationClip[]
}

// cientos 5.x: useGLTF BUKAN promise — mengembalikan { state, execute, nodes, materials }.
// Fetch auto-start (immediate), dan execute(0, path) adalah promise hasil load.
// Setup async + <Suspense> (di model-wrapper) tetap berlaku.
const { state, execute } = useGLTF(props.modelUrl)
const gltf = (await execute(0, props.modelUrl)) as unknown as GLTFResult
// TresJS useAnimations builds the actions map on composable run and updates
// the mixer every frame via useLoop's onBeforeRender (same contract as drei's
// useActions). We call it after the await, when animations are ready — mirror
// the R3F "actions[names[0]]?.reset().fadeIn(0.5).play()" effect and the
// cleanup "fadeOut(0.5).stop()".
// ref wrapper: useAnimations melakukan watch(animations) — plain array = invalid watch source
const animations = ref(gltf.animations)
const { actions } = useAnimations(animations, group as unknown as Ref<Object3D | null>)

const firstName = Object.keys(actions as Record<string, unknown>)[0] as string | undefined
if (firstName)
  actions[firstName]?.reset().fadeIn(0.5).play()

onUnmounted(() => {
  if (!firstName)
    return
  actions[firstName]?.fadeOut(0.5).stop()
})

// Override material setiap mesh dengan MeshPhysicalMaterial (punya specularIntensity
// & specularColor — paritas dengan gltfjsx): warna asli dipertahankan,
// metalness 0, roughness 0.3, specular putih.
watch(
  group,
  (value) => {
    if (!value)
      return
    value.traverse((child) => {
      const mesh = child as Mesh
      if (!mesh.isMesh)
        return

      const source = mesh.material as ISMR
      mesh.material = new MeshPhysicalMaterial({
        color: source.color.clone(),
        metalness: 0,
        roughness: 0.3,
        specularIntensity: 1,
        specularColor: new Color(0xffffff),
      })
    })
  },
  { immediate: true },
)
</script>

<template>
  <TresGroup
    ref="group"
    :scale="5"
    :rotation="[Math.PI * -0.75, 0, 0]"
  >
    <!-- GLB Google AR tidak memberi nama pada node → gltf.nodes kosong; render scene utuh -->
    <primitive :object="gltf.scene" />
  </TresGroup>
</template>
